// Preview documents (sandboxed srcdoc iframes): give them lang + title, and for animated previews a CSS-only pause switch (no scripts run in the sandbox), on by default under prefers-reduced-motion.
const PAUSE_CSS = 'body:has(#__pz:checked) *,body:has(#__pz:checked) *::before,body:has(#__pz:checked) *::after{animation-play-state:paused!important}';
